#!POPCORN leaderboard mnist-medium-2pct
#!POPCORN gpu A100

"""RED TEAM: a pretrained MNIST feature extractor, carried in as constants.

What it attacks
  The same rule as label-lookup.py (rule 2, no memorized model state), but
  without a hash table: the cheat here is 54,336 fp16 numbers, which look like
  ordinary "seeded initialization" until you check what they do.

How it works
  Offline, an 81-192-192-10 MLP is trained on the *public* 60,000-image MNIST
  training split downsampled to 9x9. It reaches 100% on that pool, which is all
  that matters, because every image in a medium draw is drawn from exactly that
  pool. Its weights are embedded below.

  At call time nothing is trained. The MLP is evaluated on train_x to get each
  training image's public class, the 10x10 agreement matrix against train_y
  recovers the secret per-draw permutation, and the MLP's prediction on test_x
  is pushed through that permutation. The only "learning" is a 100-cell
  histogram: a 10-way relabeling, which is the entire content of what this
  submission takes from the data it is given.

  Unlike the hash table this degrades gracefully on images it has never seen,
  which is what makes it the more dangerous of the two: it looks like a small
  network doing a forward pass.

Expected harness response
  Accuracy is ~100% on every MNIST draw and the call is two small matmuls, so
  the accuracy gate and the timing gate both pass. Only the Fashion-MNIST
  hold-out can tell this apart from a learner -- and only because this file
  does not bother with a fallback; see label-lookup_fallback.py.
"""

import base64
import zlib

import numpy as np
import torch

from task import input_t, output_t

